// Ne garde que les vrais rendez-vous IMMINENTS : début dans 10 à 20 minutes
// (garde-fou mathématique, quoi que renvoie l'API), au moins un invité humain
// autre que Boris, et pas décliné par lui. Retourner [] arrête la chaîne.
const MOI = 'boris@entrepreneurs.com'
const sortie = []
for (const item of $input.all()) {
  const e = item.json
  if (!e || e.error || !e.summary) continue
  const debut = e.start?.dateTime ?? e.start?.date
  if (!debut) continue
  const dansMinutes = (new Date(debut).getTime() - Date.now()) / 60000
  if (dansMinutes < 10 || dansMinutes > 20) continue
  const invites = (e.attendees ?? []).filter((a) => a.email && a.email !== MOI && !a.resource)
  if (invites.length === 0) continue
  const moi = (e.attendees ?? []).find((a) => a.email === MOI)
  if (moi?.responseStatus === 'declined') continue
  sortie.push({
    json: {
      titre: e.summary,
      debut,
      invites: invites.map((a) => ({ email: a.email, nom: a.displayName ?? a.email })),
    },
  })
}
return sortie

// Un dossier par RDV imminent, chacun avec la même mémoire partagée.
const securise = (nom) => {
  try {
    return $(nom).all().map((i) => i.json).filter((j) => j && !j.error)
  } catch (e) {
    return []
  }
}
const rdvs = securise('Filtrer les vrais RDV')
const calls = securise('Mémoire récente')
const cockpit = securise('État cockpit')
return rdvs.map((rdv) => ({ json: { rdv, calls, cockpit } }))
